import{_ as i,o as a,c as n,a4 as e}from"./chunks/framework.vNSRaLQv.js";const o=JSON.parse('{"title":"WiFi 驱动调试与连接","description":"","frontmatter":{"title":"WiFi 驱动调试与连接","date":"2026-07-25T00:00:00.000Z"},"headers":[],"relativePath":"posts/02_wifi_driver_debugging.md","filePath":"posts/02_wifi_driver_debugging.md"}'),t={name:"posts/02_wifi_driver_debugging.md"};function l(p,s,d,h,c,r){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="wifi-驱动调试与连接" tabindex="-1">WiFi 驱动调试与连接 <a class="header-anchor" href="#wifi-驱动调试与连接" aria-label="Permalink to &quot;WiFi 驱动调试与连接&quot;">​</a></h1><h2 id="wifi-硬件" tabindex="-1">WiFi 硬件 <a class="header-anchor" href="#wifi-硬件" aria-label="Permalink to &quot;WiFi 硬件&quot;">​</a></h2><ul><li>芯片：Realtek 8189FS (SDIO接口)</li><li>驱动：<code>/system/lib/modules/8189fs.ko</code></li><li>接口：wlan0, wlan1</li></ul><h2 id="驱动加载" tabindex="-1">驱动加载 <a class="header-anchor" href="#驱动加载" aria-label="Permalink to &quot;驱动加载&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">insmod</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /system/lib/modules/8189fs.ko</span></span></code></pre></div><p>加载后 dmesg 输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>RTL871X: module init start</span></span>
<span class="line"><span>RTL871X: rtl8189fs v4.3.24_18813.20160729_beta</span></span>
<span class="line"><span>######set_wifi_en: WIFI_EN_ON-0:wifi_bt_open_cnt=0</span></span>
<span class="line"><span>wifi_gpio_en = 81</span></span>
<span class="line"><span>mmc1: new high speed SDIO card at address 0001</span></span>
<span class="line"><span>RTL871X: rtw_ndev_init(wlan0) if1 mac_addr=a4:40:27:9c:f2:48</span></span>
<span class="line"><span>RTL871X: rtw_ndev_init(wlan1) if2 mac_addr=a6:40:27:9c:f2:48</span></span></code></pre></div><h2 id="踩坑-wlan0-up-后-link-is-not-ready" tabindex="-1">踩坑：wlan0 up 后 link is not ready <a class="header-anchor" href="#踩坑-wlan0-up-后-link-is-not-ready" aria-label="Permalink to &quot;踩坑：wlan0 up 后 link is not ready&quot;">​</a></h2><p><code>ifconfig wlan0 up</code> 返回成功，但 operstate 仍是 down。</p><p>分析：这是正常现象。WiFi 的 &quot;link is not ready&quot; 表示还没连上 AP，和以太网没插网线一样。IPv6 ADDRCONF 消息是信息性的，不代表错误。</p><h2 id="连接-wifi" tabindex="-1">连接 WiFi <a class="header-anchor" href="#连接-wifi" aria-label="Permalink to &quot;连接 WiFi&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 扫描</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">iwlist</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> wlan0</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> scan</span><span style="--shiki-light:#AB5959;--shiki-dark:#CB7676;"> |</span><span style="--shiki-light:#59873A;--shiki-dark:#80A665;"> grep</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> ESSID</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 启动 wpa_supplicant</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">wpa_supplicant</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -B</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -i</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> wlan0</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -c</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/wpa.conf</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#A0ADA0;--shiki-dark:#758575DD;"># 获取 IP</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">dhcpcd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> wlan0</span></span></code></pre></div><p>wpa.conf 格式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>network={</span></span>
<span class="line"><span>    ssid=&quot;Xiaomi_F5A3&quot;</span></span>
<span class="line"><span>    psk=&quot;123456789&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="踩坑-dhcpcd-锁文件冲突" tabindex="-1">踩坑：dhcpcd 锁文件冲突 <a class="header-anchor" href="#踩坑-dhcpcd-锁文件冲突" aria-label="Permalink to &quot;踩坑：dhcpcd 锁文件冲突&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span>dhcpcd: flock \`/data/misc/dhcp/dhcpcd-wlan0.pid&#39;: Try again</span></span></code></pre></div><p>解决：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes vitesse-light vitesse-dark vp-code" style="--shiki-light:#393a34;--shiki-dark:#dbd7caee;--shiki-light-bg:#ffffff;--shiki-dark-bg:#121212;" tabindex="0"><code><span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">rm</span><span style="--shiki-light:#A65E2B;--shiki-dark:#C99076;"> -f</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> /data/misc/dhcp/dhcpcd-wlan0.pid</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">killall</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> dhcpcd</span></span>
<span class="line"><span style="--shiki-light:#59873A;--shiki-dark:#80A665;">dhcpcd</span><span style="--shiki-light:#B56959;--shiki-dark:#C98A7D;"> wlan0</span></span></code></pre></div><h2 id="踩坑-dhcpcd-waiting-for-carrier" tabindex="-1">踩坑：dhcpcd waiting for carrier <a class="header-anchor" href="#踩坑-dhcpcd-waiting-for-carrier" aria-label="Permalink to &quot;踩坑：dhcpcd waiting for carrier&quot;">​</a></h2><p>WiFi 驱动加载后需要几秒才能关联 AP。dhcpcd 启动太快会等待 carrier。</p><p>解决：先 <code>wpa_supplicant</code>，等几秒再 <code>dhcpcd</code>。</p>`,21)])])}const g=i(t,[["render",l]]);export{o as __pageData,g as default};
